// magicsockvectors generates fixed vectors for SwiftailMagicsock unit tests with the Go reference implementation
// and produces Tests/SwiftailMagicsockTests/Fixtures/magicsock-vectors.json.
//
// Contents:
//   - disco: plaintext for each message type (`disco.*.AppendMarshal`) and the entire outer format with the same plaintext sealed in a NaCl box.
//       Sealing uses `box.Precompute` + `secretbox.Seal` with a fixed nonce. Go's `key.DiscoShared.Seal` generates the nonce internally,
//       so this tool calls the same calculation directly to supply a fixed nonce. It opens the generated bytes with `key.DiscoPrivate.Shared(...).Open`
//       to verify the result against Go's actual opening path before writing them.
//   - disco edge cases: the result of passing plaintext to `disco.Parse` (a message or an error).
//   - stun: `stun.Request`, `stun.Response`, and results from `stun.ParseResponse`.
//
// For keys, use SHA-256("swiftail-vectors/disco/<number>") as X25519 private key input (public test values, never production keys).
// The nonce is fixed by the message number. The output is deterministic because it uses no current time, randomness, or production values.
//
// Origin: tailscale.com v1.104.6 (`disco/disco.go`, `types/key/disco.go`, `net/stun/stun.go`), BSD-3-Clause.
//
// Run `go run ./cmd/magicsockvectors <output file>` in Tools/interop (use the environment variables in README.md).
// If no output file is supplied, write to standard output.
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"runtime/debug"

	"golang.org/x/crypto/curve25519"
)

const reference = "tailscale.com v1.104.6"

// vectors is the top level of the JSON file.
type vectors struct {
	Reference string    `json:"reference"`
	Keys      []testKey `json:"keys"`
	Disco     discoPart `json:"disco"`
	STUN      stunPart  `json:"stun"`
}

// testKey is one disco test key. seed is the X25519 private key input.
type testKey struct {
	Name   string `json:"name"`
	Seed   string `json:"seed"`
	Public string `json:"public"`
}

func main() {
	check(verifyReference())

	keys := []testKey{newTestKey("a", 1), newTestKey("b", 2)}
	out := vectors{
		Reference: reference,
		Keys:      keys,
		Disco:     buildDisco(keys[0], keys[1]),
		STUN:      buildSTUN(),
	}

	data, err := json.MarshalIndent(out, "", "  ")
	check(err)
	data = append(data, '\n')
	if len(os.Args) < 2 {
		_, err = os.Stdout.Write(data)
		check(err)
		return
	}
	check(os.WriteFile(os.Args[1], data, 0o644))
}

func newTestKey(name string, number int) testKey {
	seed := sha256.Sum256([]byte(fmt.Sprintf("swiftail-vectors/disco/%d", number)))
	var public [32]byte
	curve25519.ScalarBaseMult(&public, &seed)
	return testKey{Name: name, Seed: hexString(seed[:]), Public: hexString(public[:])}
}

// verifyReference checks that the build used the reference version of tailscale.com without a replace.
func verifyReference() error {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return fmt.Errorf("build information is missing")
	}
	for _, dep := range info.Deps {
		if dep.Path != "tailscale.com" {
			continue
		}
		if dep.Replace != nil {
			return fmt.Errorf("tailscale.com has a replace: %s", dep.Replace.Path)
		}
		if "tailscale.com "+dep.Version != reference {
			return fmt.Errorf("not the reference version: %s", dep.Version)
		}
		return nil
	}
	return fmt.Errorf("tailscale.com is not a dependency")
}

func hexString(b []byte) string { return hex.EncodeToString(b) }

func mustHex(s string) []byte {
	b, err := hex.DecodeString(s)
	check(err)
	return b
}

func check(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func require(ok bool, format string, args ...any) {
	if !ok {
		check(fmt.Errorf(format, args...))
	}
}

func equal(a, b []byte) bool { return bytes.Equal(a, b) }
